import base64, zlib, hashlib, struct

def chacha20(key, nonce, data, counter=0):
    def rotl32(v, c): return ((v << c) & 0xffffffff) | (v >> (32 - c))
    def qr(x, a, b, c, d):
        x[a] = (x[a] + x[b]) & 0xffffffff; x[d] = rotl32(x[d] ^ x[a], 16)
        x[c] = (x[c] + x[d]) & 0xffffffff; x[b] = rotl32(x[b] ^ x[c], 12)
        x[a] = (x[a] + x[b]) & 0xffffffff; x[d] = rotl32(x[d] ^ x[a], 8)
        x[c] = (x[c] + x[d]) & 0xffffffff; x[b] = rotl32(x[b] ^ x[c], 7)
    
    ctx = [0] * 16
    ctx[0], ctx[1], ctx[2], ctx[3] = struct.unpack('<IIII', b'expand 32-byte k')
    ctx[4:12] = struct.unpack('<IIIIIIII', key)
    ctx[12] = counter
    ctx[13:16] = struct.unpack('<III', nonce)
    
    res = bytearray()
    for idx in range(0, len(data), 64):
        x = list(ctx)
        for _ in range(10):
            qr(x, 0, 4, 8, 12); qr(x, 1, 5, 9, 13); qr(x, 2, 6, 10, 14); qr(x, 3, 7, 11, 15)
            qr(x, 0, 5, 10, 15); qr(x, 1, 6, 11, 12); qr(x, 2, 7, 8, 13); qr(x, 3, 4, 9, 14)
        block = struct.pack('<16I', *[(x[j] + ctx[j]) & 0xffffffff for j in range(16)])
        ctx[12] = (ctx[12] + 1) & 0xffffffff
        chunk = data[idx:idx+64]
        res += bytes(a ^ b for a, b in zip(chunk, block[:len(chunk)]))
    return bytes(res)

